// AI-GENERATED THREE.JS SCENE CODE (Synthesized by Gemma-4-31B-IT on AMD Cloud)
// Brand: "RazerNova Gaming" | 3D Mode: "elden_souls" | Structure: "floating_obelisks"
// ============================================================================
(function spawnAICustomScene(THREE, customGroup, elapsed) {
  const primaryMat = new THREE.MeshStandardMaterial({
    color: "#f59e0b",
    emissive: "#f59e0b",
    emissiveIntensity: 0.75,
    metalness: 0.85,
    roughness: 0.2
  });
  const secondaryMat = new THREE.MeshBasicMaterial({
    color: "#f72585",
    wireframe: true,
    transparent: true,
    opacity: 0.55
  });

  // Spawn 8 AI-designed 3D "floating_obelisks" monuments around the world
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const radius = 15.5;
    const holder = new THREE.Group();
    holder.position.set(Math.cos(angle) * radius, 3.8 + (i % 2) * 1.4, Math.sin(angle) * radius);

    const coreGeo = "floating_obelisks" === "neon_arches"
      ? new THREE.TorusGeometry(1.3, 0.12, 8, 24)
      : "floating_obelisks" === "orbital_rings"
        ? new THREE.IcosahedronGeometry(1.1, 0)
        : new THREE.OctahedronGeometry(1.15, 0);

    const mesh = new THREE.Mesh(coreGeo, primaryMat);
    const cage = new THREE.Mesh(new THREE.OctahedronGeometry(1.55, 0), secondaryMat);
    holder.add(mesh);
    holder.add(cage);
    holder.userData = { rotSpeed: 1.2 + (i % 3) * 0.4, floatOffset: i };
    customGroup.add(holder);
  }
})

